import {KEY,scenarioState} from '../src/model.js';
const b=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await b.newPage({viewport:{width:390,height:844}}),dir='检查记录/子功能凝练_20261021',base='http://127.0.0.1:5184';
try{await p.goto(base);await p.evaluate(({k,s})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language','zh');localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true,active:null,seen:[]}));},{k:KEY,s:scenarioState('PT01')});await p.goto(base+'/assessment?tab=当前简历');await p.locator('.resume-source-readiness').waitFor();await p.emulateMedia({reducedMotion:'reduce'});await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});await p.locator('.resume-source-readiness>p').evaluate(e=>e.scrollIntoView({block:'center'}));await p.waitForTimeout(200);const geometry=await p.evaluate(()=>{const r=e=>{const b=e.getBoundingClientRect();return {top:b.top,bottom:b.bottom,height:b.height};};return {viewport:{width:innerWidth,height:innerHeight},flow:r(document.querySelector('.flow-progress')),lastNote:r(document.querySelector('.resume-source-readiness>p')),targetLink:r(document.querySelector('.resume-source-readiness dl>div:last-child a'))};});assert.ok(geometry.lastNote.bottom<geometry.flow.top-8);assert.ok(geometry.targetLink.bottom<geometry.flow.top-8);assert.ok(geometry.targetLink.top>=0);await p.screenshot({path:dir+'/390-简历底部可达.png'});await fs.writeFile(dir+'/手机底部可达性.json',JSON.stringify({status:'pass',...geometry},null,2));console.log(JSON.stringify(geometry));}finally{await b.close();}
